<script setup lang="ts">
import {title as displayTitle,sourceName,indicator,utc,time as beijingTime,duration,http} from '../presentation/zh';
import {ref,onMounted,onUnmounted} from 'vue';import {post} from '../api/client';
const props=defineProps<{token:string}>();const data=ref<Record<string,any>>({}),error=ref(''),queried=ref('');let timer:ReturnType<typeof setInterval>;
async function refresh(){try{data.value=await post('/stream/browser/status',props.token);queried.value=new Date().toISOString();error.value='';}catch{error.value='观测记录暂不可用';}}
onMounted(()=>{void refresh();timer=setInterval(refresh,15000);});onUnmounted(()=>clearInterval(timer));
</script>
<template><section class="panel feed"><h2>在线浏览器传播观测</h2><p>页面实际查询时间：{{beijingTime(queried)}}（北京时间）</p><p>{{error||data.state||'在线实时传播尚未验证'}} · 真实在线渲染事件 {{data.samples??0}} · 双客户端在线样本 {{data.two_client_samples??0}}</p><p>确认仅证明客户端收到并按约定检查页面渲染（DOM）；不表示用户阅读。跨端网络时延没有校时依据时不作精确计算。</p><article v-for="r in data.observations||[]" :key="r.delivery_id"><p>事件 {{r.event_id}} · 来源 {{sourceName(r.source_id)}} · {{({LIVE:'在线投递',REPLAY:'历史补读',BACKFILL:'历史回填',QUALIFICATION:'资格审核通知（引用既有证据）'} as Record<string,string>)[r.delivery_type]||'未知投递'}} · {{r.replay?'补读':'连接后投递'}}</p><p>官方发布时间 <time :title="'UTC原值：'+utc(r.source_published_at)">{{beijingTime(r.source_published_at,'官方发布时间未知')}}</time> · 首次发现 <time :title="'UTC原值：'+utc(r.first_seen_at)">{{beijingTime(r.first_seen_at,'未提供')}}</time> · 入库 <time :title="'UTC原值：'+utc(r.ingested_at)">{{beijingTime(r.ingested_at,'未提供')}}</time> · 待发送记录创建 <time :title="'UTC原值：'+utc(r.outbox_created_at)">{{beijingTime(r.outbox_created_at,'未提供')}}</time> · 服务端发送 <time :title="'UTC原值：'+utc(r.sent_at)">{{beijingTime(r.sent_at,'未提供')}}</time> · 连接 {{r.connection_id}}</p><p>浏览器接收 <time :title="'UTC原值：'+utc(r.received_at)">{{beijingTime(r.received_at,'未提供')}}</time> · 页面渲染（DOM） <time :title="'UTC原值：'+utc(r.rendered_at)">{{beijingTime(r.rendered_at,'未确认渲染')}}</time> · 服务器收到确认 <time :title="'UTC原值：'+utc(r.acknowledged_at)">{{beijingTime(r.acknowledged_at,'未提供')}}</time></p><p>客户端单调时钟接收至渲染 {{r.browser_receive_to_render_ms??'未取得样本'}} 毫秒 · 时钟估计误差范围 {{r.clock_uncertainty_ms??'未估计'}} 毫秒</p></article></section></template>
